d={'worldbuilding':[F('竞技场禁止回复药剂，傀儡要求血量至少20%；这些限制与野外消耗物、退隐规则不同。',14301,14348,'fact')],'characters':[F('萧御既要保持匿名赚钱，又渴望第一人称号；风野将曝光代价与一次高赔率获利交换，双方目标并不全同。',14385,14394)],'plot':[F('战前宝石投资在危急诅咒时生效，但不消除图腾盲角；雷萨后回城受袭把任务胜利转成队友存活的新危机。',14304,14307)],'style':[F('多个冷却完成的独立系统行密集并列，把能力恢复组织成节奏转点；技能和数值取代抽象“变强”。',14325,14350)],'narrative':[F('读者已知道标记粉数量与半小时效果，角色仍将对手进攻判断为没有成果；同一战斗有公开伤害与隐藏准备两层进度。',14757,14762)],'dialogue':[F('猴子感谢早先建议而拒绝继续接济，萧御承认其靠自己混出；友谊由恩情单向关系向能力可互助的可能推进。',14402,14411)],'pacing':[F('黑赛由试探、僵持冷却、双图腾危机、低资源硬拼四段推进，胜利结算后迅速引入毒方与下一场，形成多目标接续。',14222,14262)],'themes':[F('274章团队连控让十个人成为团队，276章又展示依赖队友降低警觉；作品同时论证合作收益与独行警戒，不能压成单一团结论。',14693,14716)],'continuity':[F('两轮32+35=67而正文称68，是统计异常；牛仔明确死，柠檬宿命已返城，其余七人被标记，不能记为全队无伤。',14599,14607)]}
